/// <summary>
/// 简单文件存储实现
/// </summary>
[System.ComponentModel.Description("文件存储任务仓储")]
public class TodoRepository : ITodoRepository
{
    private readonly ILogger<TodoRepository> _logger;
    private readonly IMemoryCache _cache;
    private readonly string _storagePath;
    private readonly SemaphoreSlim _fileLock = new(1, 1);
    private readonly Timer _cacheCleanupTimer;
    
    private readonly string _tasksFilePath;
    private readonly string _indexFilePath;
    private readonly ConcurrentDictionary<Guid, DateTimeOffset> _lastModified = new();
    
    public TodoRepository(
        ILogger<TodoRepository> logger,
        IMemoryCache cache)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        
        // 设置存储路径
        _storagePath = Path.Combine(Directory.GetCurrentDirectory(), "data", "todos");
        _tasksFilePath = Path.Combine(_storagePath, "tasks.json");
        _indexFilePath = Path.Combine(_storagePath, "index.json");
        
        // 确保目录存在
        Directory.CreateDirectory(_storagePath);
        
        // 初始化存储文件
        InitializeStorage();
        
        // 定时清理缓存
        _cacheCleanupTimer = new Timer(CleanupCache, null, TimeSpan.FromMinutes(5), TimeSpan.FromMinutes(5));
    }
    
    public async Task<TodoItem> CreateAsync(TodoItem task, CancellationToken cancellationToken = default)
    {
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var tasks = await LoadTasksAsync(cancellationToken);
            
            // 检查ID是否已存在
            if (tasks.Any(t => t.Id == task.Id))
            {
                throw new InvalidOperationException($"任务 ID {task.Id} 已存在");
            }
            
            tasks.Add(task);
            await SaveTasksAsync(tasks, cancellationToken);
            
            // 更新缓存
            _cache.Set($"todo:{task.Id}", task, TimeSpan.FromMinutes(30));
            _lastModified[task.Id] = DateTimeOffset.UtcNow;
            
            _logger.LogInformation("任务创建成功: {TaskId}, 标题: {Title}", task.Id, task.Title);
            
            return task;
        }
        finally
        {
            _fileLock.Release();
        }
    }
    
    public async Task<TodoItem?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var cacheKey = $"todo:{id}";
        
        if (_cache.TryGetValue(cacheKey, out TodoItem? cachedTask))
        {
            return cachedTask;
        }
        
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var tasks = await LoadTasksAsync(cancellationToken);
            var task = tasks.FirstOrDefault(t => t.Id == id);
            
            if (task != null)
            {
                _cache.Set(cacheKey, task, TimeSpan.FromMinutes(30));
            }
            
            return task;
        }
        finally
        {
            _fileLock.Release();
        }
    }
    
    public async Task<List<TodoItem>> GetByIdsAsync(List<Guid> ids, CancellationToken cancellationToken = default)
    {
        var result = new List<TodoItem>();
        
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var tasks = await LoadTasksAsync(cancellationToken);
            
            foreach (var id in ids)
            {
                var cacheKey = $"todo:{id}";
                if (_cache.TryGetValue(cacheKey, out TodoItem? cachedTask))
                {
                    result.Add(cachedTask);
                    continue;
                }
                
                var task = tasks.FirstOrDefault(t => t.Id == id);
                if (task != null)
                {
                    result.Add(task);
                    _cache.Set(cacheKey, task, TimeSpan.FromMinutes(30));
                }
            }
        }
        finally
        {
            _fileLock.Release();
        }
        
        return result;
    }
    
    public async Task<List<TodoItem>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var cacheKey = "todos:all";
        
        if (_cache.TryGetValue(cacheKey, out List<TodoItem>? cachedTasks))
        {
            return cachedTasks;
        }
        
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var tasks = await LoadTasksAsync(cancellationToken);
            
            _cache.Set(cacheKey, tasks, TimeSpan.FromMinutes(15));
            
            return tasks;
        }
        finally
        {
            _fileLock.Release();
        }
    }
    
    public async Task<TodoItem> UpdateAsync(TodoItem task, CancellationToken cancellationToken = default)
    {
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var tasks = await LoadTasksAsync(cancellationToken);
            var existingIndex = tasks.FindIndex(t => t.Id == task.Id);
            
            if (existingIndex == -1)
            {
                throw new KeyNotFoundException($"任务 {task.Id} 不存在");
            }
            
            tasks[existingIndex] = task;
            await SaveTasksAsync(tasks, cancellationToken);
            
            // 更新缓存
            _cache.Set($"todo:{task.Id}", task, TimeSpan.FromMinutes(30));
            _cache.Remove("todos:all"); // 清除全量缓存
            
            _lastModified[task.Id] = DateTimeOffset.UtcNow;
            
            _logger.LogInformation("任务更新成功: {TaskId}, 标题: {Title}", task.Id, task.Title);
            
            return task;
        }
        finally
        {
            _fileLock.Release();
        }
    }
    
    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var tasks = await LoadTasksAsync(cancellationToken);
            var task = tasks.FirstOrDefault(t => t.Id == id);
            
            if (task == null)
            {
                return false;
            }
            
            tasks.Remove(task);
            await SaveTasksAsync(tasks, cancellationToken);
            
            // 清除缓存
            _cache.Remove($"todo:{id}");
            _cache.Remove("todos:all");
            _lastModified.TryRemove(id, out _);
            
            _logger.LogInformation("任务删除成功: {TaskId}", id);
            
            return true;
        }
        finally
        {
            _fileLock.Release();
        }
    }
    
    public async Task<List<TodoItem>> GetPagedAsync(TodoQuery query, CancellationToken cancellationToken = default)
    {
        var allTasks = await GetAllAsync(cancellationToken);
        
        // 应用过滤条件
        var filteredTasks = FilterTasks(allTasks, query);
        
        // 应用排序
        var sortedTasks = SortTasks(filteredTasks, query);
        
        // 应用分页
        var totalCount = sortedTasks.Count;
        var pagedTasks = sortedTasks
            .Skip((query.PageNumber - 1) * query.PageSize)
            .Take(query.PageSize)
            .ToList();
        
        return pagedTasks;
    }
    
