    {
        var cacheKey = $"todos:assignee:{assigneeId}";
        
        if (_cache.TryGetValue(cacheKey, out List<TodoItem>? cachedTasks))
        {
            return cachedTasks;
        }
        
        var allTasks = await GetAllAsync(cancellationToken);
        var tasks = allTasks.Where(t => t.AssigneeId == assigneeId).ToList();
        
        _cache.Set(cacheKey, tasks, TimeSpan.FromMinutes(15));
        
        return tasks;
