    public async Task<List<TodoItem>> GetOverdueAsync(CancellationToken cancellationToken = default)
    {
        var cacheKey = "todos:overdue";
        
        if (_cache.TryGetValue(cacheKey, out List<TodoItem>? cachedTasks))
        {
            return cachedTasks;
        }
        
        var allTasks = await GetAllAsync(cancellationToken);
        var now = DateTimeOffset.UtcNow;
        
        var overdueTasks = allTasks.Where(t => 
            t.DueDate.HasValue && 
            t.DueDate < now && 
            t.Status != TaskStatus.Completed &&
            t.Status != TaskStatus.Cancelled).ToList();
        
        _cache.Set(cacheKey, overdueTasks, TimeSpan.FromMinutes(5));
        
        return overdueTasks;
    }
    
