    public async Task<List<TodoItem>> SearchAsync(string searchText, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(searchText))
        {
            return await GetAllAsync(cancellationToken);
        }
        
        var allTasks = await GetAllAsync(cancellationToken);
        var lowerSearchText = searchText.ToLower();
        
        return allTasks.Where(t => 
            t.Title.ToLower().Contains(lowerSearchText) ||
            (t.Description != null && t.Description.ToLower().Contains(lowerSearchText)) ||
            t.Tags.Any(tag => tag.ToLower().Contains(lowerSearchText)) ||
            (t.AssigneeName != null && t.AssigneeName.ToLower().Contains(lowerSearchText))).ToList();
    }
    
