    public async Task<List<TodoItem>> GetWithDependenciesAsync(Guid taskId, CancellationToken cancellationToken = default)
    {
        var task = await GetByIdAsync(taskId, cancellationToken);
        if (task == null)
        {
            return new List<TodoItem>();
        }
        
        var dependencies = await GetByIdsAsync(task.Dependencies, cancellationToken);
        var dependents = await GetDependentsAsync(taskId, cancellationToken);
        
        var result = new List<TodoItem> { task };
        result.AddRange(dependencies);
        result.AddRange(dependents);
        
        return result.Distinct().ToList();
    }
    
    public async Task<List<TodoItem>> GetDependenciesAsync(Guid taskId, CancellationToken cancellationToken = default)
    {
        var task = await GetByIdAsync(taskId, cancellationToken);
        if (task?.Dependencies == null || !task.Dependencies.Any())
        {
            return new List<TodoItem>();
        }
        
        return await GetByIdsAsync(task.Dependencies, cancellationToken);
    }
    
