    public async Task<Dictionary<string, int>> GetTagStatisticsAsync(CancellationToken cancellationToken = default)
    {
        var allTasks = await GetAllAsync(cancellationToken);
        var tagStats = new Dictionary<string, int>();
        
        foreach (var task in allTasks)
        {
            foreach (var tag in task.Tags)
            {
                tagStats[tag] = tagStats.GetValueOrDefault(tag, 0) + 1;
            }
        }
        
        return tagStats.OrderByDescending(kvp => kvp.Value).ToDictionary(kvp => kvp.Key, kvp => kvp.Value);
    }
    
    public async Task<Dictionary<string, int>> GetAssigneeStatisticsAsync(CancellationToken cancellationToken = default)
    {
        var allTasks = await GetAllAsync(cancellationToken);
        var assigneeStats = new Dictionary<string, int>();
        
        foreach (var task in allTasks.Where(t => !string.IsNullOrEmpty(t.AssigneeName)))
        {
            var assigneeName = task.AssigneeName!;
            assigneeStats[assigneeName] = assigneeStats.GetValueOrDefault(assigneeName, 0) + 1;
        }
        
        return assigneeStats.OrderByDescending(kvp => kvp.Value).ToDictionary(kvp => kvp.Key, kvp => kvp.Value);
    }
    
