    public async Task<List<TodoItem>> GetTasksWithPendingDependenciesAsync(CancellationToken cancellationToken = default)
    {
        var allTasks = await GetAllAsync(cancellationToken);
        var tasksWithPendingDeps = new List<TodoItem>();
        
        foreach (var task in allTasks.Where(t => t.Dependencies.Any()))
        {
            var dependencies = await GetByIdsAsync(task.Dependencies, cancellationToken);
            var pendingDependencies = dependencies.Where(d => d.Status != TaskStatus.Completed).ToList();
            
            if (pendingDependencies.Any())
            {
                tasksWithPendingDeps.Add(task);
            }
        }
        
        return tasksWithPendingDeps;
    }
    
