            t.CreatedAt >= startDate && 
            t.CreatedAt <= endDate).ToList();
    }
    
    // 私有辅助方法
    
    private void InitializeStorage()
    {
        try
        {
            // 创建任务文件
            if (!File.Exists(_tasksFilePath))
            {
                File.WriteAllText(_tasksFilePath, "[]");
            }
            
            // 创建索引文件
            if (!File.Exists(_indexFilePath))
            {
                File.WriteAllText(_indexFilePath, "{}");
            }
            
            _logger.LogInformation("存储初始化完成: {StoragePath}", _storagePath);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "存储初始化失败");
            throw;
        }
    }
    
    private async Task<List<TodoItem>> LoadTasksAsync(CancellationToken cancellationToken = default)
    {
        try
        {
            var jsonContent = await File.ReadAllTextAsync(_tasksFilePath, cancellationToken);
            
            if (string.IsNullOrWhiteSpace(jsonContent))
            {
                return new List<TodoItem>();
            }
            
            var options = new JsonSerializerOptions
            {
                PropertyNameCaseInsensitive = true,
                Converters = { new JsonStringEnumConverter() }
            };
            
            var tasks = JsonSerializer.Deserialize<List<TodoItem>>(jsonContent, options) ?? new List<TodoItem>();
            
            return tasks;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "加载任务数据失败");
            return new List<TodoItem>();
        }
    }
    
    private async Task SaveTasksAsync(List<TodoItem> tasks, CancellationToken cancellationToken = default)
    {
        try
        {
            var options = new JsonSerializerOptions
            {
                WriteIndented = true,
                Converters = { new JsonStringEnumConverter() }
            };
            
            var jsonContent = JsonSerializer.Serialize(tasks, options);
            await File.WriteAllTextAsync(_tasksFilePath, jsonContent, cancellationToken);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "保存任务数据失败");
            throw;
        }
    }
    
    private List<TodoItem> FilterTasks(List<TodoItem> tasks, TodoQuery query)
    {
        var filtered = tasks.AsEnumerable();
        
        if (query.Status.HasValue)
        {
            filtered = filtered.Where(t => t.Status == query.Status.Value);
        }
        
        if (query.Priority.HasValue)
        {
            filtered = filtered.Where(t => t.Priority == query.Priority.Value);
        }
        
        if (query.Category.HasValue)
        {
            filtered = filtered.Where(t => t.Category == query.Category.Value);
        }
        
        if (query.AssigneeId.HasValue)
        {
            filtered = filtered.Where(t => t.AssigneeId == query.AssigneeId.Value);
        }
        
        if (query.DueDateFrom.HasValue)
        {
            filtered = filtered.Where(t => t.DueDate >= query.DueDateFrom.Value);
        }
        
        if (query.DueDateTo.HasValue)
        {
            filtered = filtered.Where(t => t.DueDate <= query.DueDateTo.Value);
        }
        
        if (!string.IsNullOrWhiteSpace(query.SearchText))
        {
            var searchText = query.SearchText.ToLower();
            filtered = filtered.Where(t => 
                t.Title.ToLower().Contains(searchText) ||
                (t.Description != null && t.Description.ToLower().Contains(searchText)) ||
                t.Tags.Any(tag => tag.ToLower().Contains(searchText)));
        }
        
        if (query.Tags?.Any() == true)
        {
            filtered = filtered.Where(t => 
                query.Tags.Any(queryTag => 
                    t.Tags.Contains(queryTag, StringComparer.OrdinalIgnoreCase)));
        }
        
        return filtered.ToList();
    }
    
    private List<TodoItem> SortTasks(List<TodoItem> tasks, TodoQuery query)
    {
        var sorted = tasks.AsEnumerable();
        
        if (!string.IsNullOrWhiteSpace(query.SortBy))
        {
            sorted = query.SortBy.ToLower() switch
            {
                "title" => query.SortDescending ? sorted.OrderByDescending(t => t.Title) : sorted.OrderBy(t => t.Title),
                "priority" => query.SortDescending ? sorted.OrderByDescending(t => t.Priority) : sorted.OrderBy(t => t.Priority),
                "status" => query.SortDescending ? sorted.OrderByDescending(t => t.Status) : sorted.OrderBy(t => t.Status),
                "category" => query.SortDescending ? sorted.OrderByDescending(t => t.Category) : sorted.OrderBy(t => t.Category),
                "createdat" => query.SortDescending ? sorted.OrderByDescending(t => t.CreatedAt) : sorted.OrderBy(t => t.CreatedAt),
                "modifiedat" => query.SortDescending ? sorted.OrderByDescending(t => t.ModifiedAt) : sorted.OrderBy(t => t.ModifiedAt),
                "duedate" => query.SortDescending ? sorted.OrderByDescending(t => t.DueDate) : sorted.OrderBy(t => t.DueDate),
                "estimatedhours" => query.SortDescending ? sorted.OrderByDescending(t => t.EstimatedHours) : sorted.OrderBy(t => t.EstimatedHours),
                "progress" => query.SortDescending ? sorted.OrderByDescending(t => t.Progress) : sorted.OrderBy(t => t.Progress),
                _ => query.SortDescending ? sorted.OrderByDescending(t => t.CreatedAt) : sorted.OrderBy(t => t.CreatedAt)
            };
        }
        else
        {
            // 默认排序：按创建时间倒序
            sorted = sorted.OrderByDescending(t => t.CreatedAt);
        }
        
        return sorted.ToList();
    }
    
    private void CleanupCache(object? state)
    {
        try
        {
            // 清理过期的任务缓存
            var cacheKeys = _cache.GetKeys<string>();
            var taskKeys = cacheKeys.Where(key => key.StartsWith("todo:")).ToList();
            
            foreach (var key in taskKeys)
            {
                // 检查任务是否已被删除
                if (key.StartsWith("todo:") && key != "todo:all")
                {
                    var taskId = key.Substring(5);
                    if (Guid.TryParse(taskId, out var id))
                    {
                        if (_lastModified.TryGetValue(id, out var lastModified))
                        {
                            // 如果任务超过1小时未修改，清除缓存
                            if (DateTimeOffset.UtcNow - lastModified > TimeSpan.FromHours(1))
                            {
                                _cache.Remove(key);
                            }
                        }
                    }
                }
            }
            
            _logger.LogDebug("缓存清理完成，清理了 {Count} 个键", taskKeys.Count);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "缓存清理失败");
        }
    }
    
    public void Dispose()
    {
        _cacheCleanupTimer?.Dispose();
        _fileLock?.Dispose();
    }
}

/// <summary>
/// 事件总线实现
/// </summary>
public class EventBus : IEventBus
{
    private readonly ILogger<EventBus> _logger;
    private readonly Dictionary<Type, List<Func<object, CancellationToken, Task>>> _handlers;
    
    public EventBus(ILogger<EventBus> logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _handlers = new Dictionary<Type, List<Func<object, CancellationToken, Task>>>();
    }
    
    public async Task PublishAsync<T>(T eventData, CancellationToken cancellationToken = default) where T : class
    {
        var eventType = typeof(T);
        
        if (_handlers.TryGetValue(eventType, out var handlers))
        {
            var tasks = handlers.Select(handler => 
            {
                try
                {
                    return handler(eventData, cancellationToken);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "事件处理器执行失败: {EventType}", eventType.Name);
                    return Task.CompletedTask;
                }
            });
            
            await Task.WhenAll(tasks);
        }
        
        _logger.LogDebug("事件发布完成: {EventType}", eventType.Name);
    }
    
    public void Subscribe<T>(Func<T, CancellationToken, Task> handler) where T : class
    {
        var eventType = typeof(T);
        
        if (!_handlers.ContainsKey(eventType))
        {
            _handlers[eventType] = new List<Func<object, CancellationToken, Task>>();
        }
        
        _handlers[eventType].Add((data, ct) => handler((T)data, ct));
    }
}

// 程序入口点
var builder = WebApplication.CreateBuilder(args);

// 配置服务
builder.Services.AddMemoryCache();
builder.Services.AddScoped<ITodoRepository, TodoRepository>();
builder.Services.AddScoped<IEventBus, EventBus>();

// 添加Scrutor自动注册
builder.Services.Scan(scan => scan
    .FromAssemblies(Assembly.GetExecutingAssembly())
    .AddClasses(classes => classes.AssignableTo<ITodoRepository>())
    .AsImplementedInterfaces()
    .WithScopedLifetime());

// 配置应用
var app = builder.Build();

// 配置中间件
if (app.Environment.IsDevelopment())
{
    app.UseDeveloperExceptionPage();
}

app.UseRouting();
app.UseEndpoints(endpoints =>
{
    endpoints.MapGet("/", () => "Todo Repository is running!");
    
    // 健康检查端点
    endpoints.MapGet("/health", () => Results.Ok(new { Status = "Healthy", Timestamp = DateTime.UtcNow }));
    
    // 获取所有任务端点
    endpoints.MapGet("/tasks", async (ITodoRepository repository) =>
    {
        var tasks = await repository.GetAllAsync();
        return Results.Ok(tasks);
    });
    
    // 根据ID获取任务端点
    endpoints.MapGet("/tasks/{id:guid}", async (Guid id, ITodoRepository repository) =>
    {
        var task = await repository.GetByIdAsync(id);
        return task != null ? Results.Ok(task) : Results.NotFound();
    });
});

Console.WriteLine("Todo Repository started successfully!");
Console.WriteLine($"Storage Path: {Path.Combine(Directory.GetCurrentDirectory(), "data", "todos")}");
Console.WriteLine("Press Ctrl+C to shutdown");

app.Run();